        if (reverted) {
            assert(afterPastBlockTime == beforePastBlockTime && afterBalance == beforeBalance);
        } else {
            assert(afterPastBlockTime == beforePastBlockTime + 1 && afterBalance == beforeBalance + sendAmount);
        }
    }

    receive() external payable {}
}

