contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint setTime) public payable {
        require(address(this).balance >= amount);
        require(setTime > 0);

        // Establish a known pastBlockTime so the next call has a meaningful timestamp boundary.
        (bool setupOk, ) = address(c).call{value: 10 ether}(abi.encodeWithSignature("fallback()"));
        require(setupOk);
        // After setup, pastBlockTime is exactly the timestamp of this transaction plus 1.
        // Use block.timestamp > c.pastBlockTime() to test whether fallback succeeds or reverts,
        // and verify a successful fallback updates pastBlockTime to block.timestamp() + 1.

        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        assert(
            reverted == (amount != 10 ether || block.timestamp <= beforeTime)
        );

        assert(
            !reverted
                ? (afterTime == block.timestamp + 1 && afterBalance == beforeBalance + amount)
                : (afterTime == beforeTime && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

