contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint64 dummy) public payable {
        require(amount == 10 ether, "need exactly 10 ether");

        // Ensure this test contract has enough balance to send the required value.
        require(address(this).balance >= amount, "insufficient test contract balance");

        // Read the before-state through c's public getter.
        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // Make the deciding call. msg.value must be exactly 10 ether.
        // A revert is expected only when block.timestamp <= beforeTime.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the after-state through c's public surface.
        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // General rule:
        // - If the call reverts, timestamp was not greater than beforeTime and state/value are unchanged.
        // - If the call succeeds, timestamp was greater than beforeTime, pastBlockTime is now the call's
        //   timestamp plus one, and the balance is either unchanged (non-transferred branch) or zero
        //   (transferred branch).
        assert(
            (reverted && afterTime == beforeTime && afterBalance == beforeBalance)
            ||
            (!reverted && afterTime > beforeTime && (afterBalance == beforeBalance || afterBalance == 0))
        );
    }

    receive() external payable {}
}

