    }

    function run(uint amount, uint timestamp) public payable {
        require(amount == 10 ether);
        require(timestamp > c.pastBlockTime());
        require(address(this).balance >= amount);
        require(timestamp > block.timestamp);

        // Keep the contract's timestamp below our supplied one by using a large value.
        // Prepare balance before the deciding call.
        uint beforeBalance = address(c).balance;

        // Advance the contract's pastBlockTime to a value below the target timestamp using
        // an earlier call with the same amount, if needed.  But since one run() call is
        // a single transaction, we can only make the deciding call.
        // We rely on the fact that the deployed c has pastBlockTime == 0, so any positive
        // timestamp from the parameter should be allowed.  However, the Ethereum timestamp
        // is fixed per block, so we cannot set it.  We want to test the state-changing rule:
        // after a successful call with 10 ether, pastBlockTime becomes the block timestamp + 1
        // and the balance increases by 10 ether.
        // To satisfy the require(block.timestamp > pastBlockTime), we need the call to be
        // the first fallback call, with pastBlockTime == 0.  Since the tester deploys a fresh
        // contract, pastBlockTime is 0.  So pastBlockTime < block.timestamp is true.

        // Make the deciding call.
        (bool success, ) = address(c).call{value: amount}("");

        // Read after values.
        uint afterBalance = address(c).balance;
        uint afterPastBlockTime = c.pastBlockTime();

        assert(
            success &&
            afterPastBlockTime == block.timestamp + 1 &&
            afterBalance == beforeBalance + amount
        );
    }
}

