        require(address(this).balance >= amount);

        // First call: may revert depending on initial pastBlockTime vs block.timestamp.
        // We ignore its outcome, but we make sure at least one call succeeds by
        // trying again below only after a successful state update if needed.
        // To avoid depending on revert handling around fallback, we perform the
        // deciding call and assert on its observable effect.
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the call succeeds, c's balance must not have increased;
        // with exactly 10 ether sent and no payout, it should increase by 10 ether
        // unless block.number % 15 == 0, in which case c's balance decreases.
        // For all inputs, a successful call never causes c's balance to grow by
        // more than the ether sent and never causes it to shrink by more than
        // its prior balance.
        assert(
            reverted
                ? address(c).balance == beforeBalanceC
                : address(c).balance <= beforeBalanceC + amount &&
                  beforeBalanceC <= beforeBalanceC + amount
        );
    }

    receive() external payable {}
}

