contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint timestamp) public payable {
        require(address(this).balance >= amount);

        uint before = c.pastBlockTime();
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

