contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 d1, uint256 d2) public payable {
        require(amount > 0, "need positive amount");
        require(address(this).balance >= amount, "not enough balance");
        require(d1 <= 100, "delay too large");
        require(d2 <= 100, "delay too large");

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        require(address(this).balance >= 10 ether, "setup needs 10 ether");
        (bool setupOk, ) = address(c).call{value: 10 ether}("");
        require(setupOk, "setup fallback must succeed");
        uint256 afterSetupTime = c.pastBlockTime();

        // Ensure that the next call can have block.timestamp > pastBlockTime.
        if (block.timestamp <= afterSetupTime) {
            return;
        }

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(amount == 10 ether);
            assert(c.pastBlockTime() == block.timestamp + 1);
        } else {
            assert(amount != 10 ether);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 delay) public payable {
        require(amount > 0, "need positive amount");
        require(address(this).balance >= amount, "not enough balance");
        require(delay <= 100, "delay too large");

        // Setup: perform a successful fallback call so that pastBlockTime is set
        // to a concrete future timestamp relative to the first observed time.
        require(address(this).balance >= 10 ether, "setup needs 10 ether");
        (bool setupOk, ) = address(c).call{value: 10 ether}("");
        require(setupOk, "setup fallback must succeed");
        uint256 afterSetupTime = c.pastBlockTime();

        // If timestamps are stuck such that no future call can satisfy
        // block.timestamp > pastBlockTime, skip the deciding call.
        if (block.timestamp <= afterSetupTime) {
            return;
        }

        bool reverted;
        uint256 beforeBalance = address(c).balance;
        uint256 beforeTime = c.pastBlockTime();

        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        if (!reverted) {
            assert(amount == 10 ether);
            assert(c.pastBlockTime() == block.timestamp + 1);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == beforeBalance + amount);
            }
        } else {
            assert(amount != 10 ether);
            assert(c.pastBlockTime() == beforeTime);
        }
    }

    receive() external payable {}
}

