        uint256 balanceBefore = address(c).balance;
        (bool success, ) = address(c).call{value: 10 ether}();

        uint256 balanceAfter = address(c).balance;
        bool transferredAll = (balanceAfter == 0);
        bool blockIsMultipleOf15 = (blockNumMod == 0);

        assert(
            success &&
            pastAfterSetup < targetTimestamp &&
            (c.pastBlockTime() == targetTimestamp + 1) &&
            (blockIsMultipleOf15 ? transferredAll : (balanceAfter == balanceBefore + 10 ether))
        );
    }

    receive() external payable {}
}

