        uint afterPastBlockTime = c.pastBlockTime();

        // General rule: if the call did not revert, then pastBlockTime was advanced
        // to a value strictly greater than the block timestamp at the time of the call,
        // and the balance moved according to the block.number condition.
        if (!reverted) {
            // pastBlockTime must have increased and be at least block.timestamp + 1
            // (the contract sets it to block.timestamp + 1)
            assert(afterPastBlockTime >= block.timestamp + 1);
        } else {
            // If it reverted, pastBlockTime must not have changed
            assert(afterPastBlockTime == beforePastBlockTime);
        }
    }

    receive() external payable {}
}

